contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(uint256 amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        bool reverted = false;
        // state-changing call must be top-level; use try only for revert capture
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

